std::mutex resource_mtx;
int protected_counter = 0;

void update_shared_resource() {
    // RAII lock: ensures unlock happens automatically
    std::lock_guard<std::mutex> lock(resource_mtx);

    // Critical Section
    protected_counter += 10;

    // Lock is released when 'lock' leaves scope
}

// Manual lock/unlock (less safe)
void manual_access() {
    resource_mtx.lock();
    protected_counter--;
    resource_mtx.unlock();
}
